const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if('IntersectionObserver'in window&&!reduced){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(items=>items.forEach(item=>{if(item.isIntersecting){item.target.classList.add('visible');observer.unobserve(item.target)}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));}
let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;document.documentElement.style.setProperty('--progress',`${total>0?scrollY/total*100:0}%`);ticking=false})},{passive:true});
const menu=$('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');$('.mobile-nav').hidden=!open});$$('.mobile-nav a').forEach(el=>el.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');$('.mobile-nav').hidden=true}));
function getSaved(){try{return JSON.parse(localStorage.getItem('palacete-shortlist')||'[]')}catch{return[]}}function saveList(list){try{localStorage.setItem('palacete-shortlist',JSON.stringify(list))}catch{}}
const favorite=$('.favorite');function updateFavorite(){const saved=getSaved().includes(document.body.dataset.concept);favorite.setAttribute('aria-pressed',String(saved));favorite.textContent=saved?'♥ Shortlisted':'♡ Shortlist'}updateFavorite();favorite.addEventListener('click',()=>{const id=document.body.dataset.concept,list=getSaved();saveList(list.includes(id)?list.filter(x=>x!==id):[...list,id]);updateFavorite()});
$('#concept-select').addEventListener('change',e=>{location.href=e.target.value+'.html'});$('#hide-controls').addEventListener('click',()=>{$('.concept-bar').hidden=true;$('#restore-controls').hidden=false});$('#restore-controls').addEventListener('click',()=>{$('.concept-bar').hidden=false;$('#restore-controls').hidden=true});
const enquiry=$('#enquiry'),form=$('#stay-form');function dateString(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}function tomorrow(value){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+1);return dateString(d)}form.elements.arrival.min=dateString(new Date());form.elements.departure.min=tomorrow(form.elements.arrival.min);form.elements.arrival.addEventListener('change',()=>{form.elements.departure.min=tomorrow(form.elements.arrival.value||dateString(new Date()));if(form.elements.departure.value<form.elements.departure.min)form.elements.departure.value=''});
function openEnquiry(room){$$('dialog[open]').forEach(d=>d.close());form.hidden=false;$('#enquiry-review').hidden=true;$('#error').textContent='';if(room)form.elements.room.value=room;enquiry.showModal();$('.mobile-nav').hidden=true;menu.setAttribute('aria-expanded','false')}
$$('[data-enquire]').forEach(b=>b.addEventListener('click',()=>openEnquiry()));$$('[data-room]').forEach(b=>b.addEventListener('click',()=>openEnquiry(b.dataset.room)));
form.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(!d.name.trim()){$('#error').textContent='Please enter your name.';return}if(d.arrival<dateString(new Date())||d.departure<=d.arrival){$('#error').textContent='Please select valid arrival and departure dates.';return}const readable=x=>new Date(x+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}),nights=Math.round((Date.parse(d.departure+'T12:00:00')-Date.parse(d.arrival+'T12:00:00'))/86400000);const text=`Hello Necila, I would like to enquire about a stay at Palacete Rodrigues.\n\nName: ${d.name.trim()}\nEmail: ${d.email}\nArrival: ${readable(d.arrival)}\nDeparture: ${readable(d.departure)}\nNights: ${nights}\nAdults: ${d.adults}\nChildren: ${d.children}\nRoom: ${d.room}${d.notes.trim()?'\nNotes: '+d.notes.trim():''}\n\nPlease share availability, total rates and booking terms. Thank you!`;$('#enquiry-text').textContent=text;$('#send-wa').href='https://wa.me/919422056467?text='+encodeURIComponent(text);$('#send-email').href='mailto:info@palacetegoa.com?subject='+encodeURIComponent('Stay enquiry | '+readable(d.arrival))+'&body='+encodeURIComponent(text);form.hidden=true;$('#enquiry-review').hidden=false;$('#send-wa').focus();});
$('#edit-enquiry').addEventListener('click',()=>{form.hidden=false;$('#enquiry-review').hidden=true;form.elements.name.focus()});
$$('.dialog-close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
const roomData=[['Double Room','bed','A traditional double bedroom with a carved four-poster bed and heritage furniture.'],['AC Double Room','bed1','An air-conditioned double room with period furniture and soft patterned fabrics.'],['Heritage Suite','bed2','A suite with the mansion’s distinctive carved furniture and old-world character.']];let selectedRoom='';$$('[data-room-detail]').forEach(b=>b.addEventListener('click',()=>{const r=roomData[Number(b.dataset.roomDetail)];selectedRoom=r[0];$('#detail-name').textContent=r[0];$('#detail-description').textContent=r[2];$('#detail-photo').src='../assets/'+r[1]+'-enhanced.jpg';$('#detail-photo').alt=r[0];$('#room-detail').showModal()}));$('#detail-enquire').addEventListener('click',()=>openEnquiry(selectedRoom));
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$$('.room').forEach(r=>{r.hidden=b.dataset.filter!=='all'&&r.dataset.type!==b.dataset.filter;if(!r.hidden)r.classList.add('visible')})}));
const photos=[['gardenview','A moment by the pool.'],['furniture','A house full of character.'],['ch6','Craft, in every detail.']];let photoIndex=0;function showPhoto(i){photoIndex=(i+photos.length)%photos.length;const p=photos[photoIndex];$('#lightbox-photo').src='../assets/'+p[0]+'-enhanced.jpg';$('#lightbox-photo').alt=p[1];$('#photo-caption').textContent=`${photoIndex+1} / ${photos.length} — ${p[1]}`};$$('[data-gallery]').forEach(b=>b.addEventListener('click',()=>{showPhoto(Number(b.dataset.gallery));$('#lightbox').showModal()}));$('#photo-prev').addEventListener('click',()=>showPhoto(photoIndex-1));$('#photo-next').addEventListener('click',()=>showPhoto(photoIndex+1));$('#lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowRight')showPhoto(photoIndex+1);if(e.key==='ArrowLeft')showPhoto(photoIndex-1)});
